			root := t.TempDir()
			if err := os.Chmod(root, 0700); err != nil {
				t.Fatal(err)
			}
			before := map[string][]byte{}
			for name, value := range map[string]any{"netbird-pin.json": previous.Pin, "netbird.json": previous.Enrollment} {
