func (enrollment *managedHostEnrollment) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	if request.URL.Path == "/v1/runtime/worker-refresh" {
		enrollment.refreshRuntimeWorker(writer, request)
		return
	}
	if request.URL.Path == "/v1/runtime/worker-bind" {
		enrollment.bindRuntimeWorker(writer, request)
		return
	}
	if request.Method != http.MethodPost || request.URL.Path != "/v1/host-enrollment" || request.TLS == nil ||
		request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		http.Error(writer, "invalid host enrollment request", http.StatusBadRequest)
		return
	}
	snapshot := enrollment.fencer.Current()
	if !snapshot.CanMutate() {
		http.Error(writer, "regional authority is not writable", http.StatusServiceUnavailable)
		return
	}
	peerIP, _, err := net.SplitHostPort(request.RemoteAddr)
	if err != nil || net.ParseIP(peerIP) == nil {
		http.Error(writer, "direct private peer is required", http.StatusForbidden)
		return
	}
	wire, err := io.ReadAll(io.LimitReader(request.Body, hostenroll.MaxRequestBytes+1))
	if err != nil || len(wire) > hostenroll.MaxRequestBytes {
		http.Error(writer, "host enrollment request is too large", http.StatusRequestEntityTooLarge)
		return
	}
	enrollmentRequest, descriptor, err := hostenroll.ParseRequest(wire, time.Now().UTC())
	if err != nil {
		var historical hostenroll.Request
		if json.Unmarshal(wire, &historical, json.RejectUnknownMembers(true)) != nil ||
			historical.IssuedAt.IsZero() || !historical.IssuedAt.Before(time.Now().Add(-48*time.Hour)) {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		enrollmentRequest, descriptor, err = hostenroll.ParseRequest(wire, historical.IssuedAt.Add(time.Second))
		if err != nil {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		grant, _, readErr := enrollment.grants.Read(request.Context(), enrollmentRequest.InstanceID)
		stored := grant.Request
		if enrollmentRequest.Operation == "renew" {
			stored = grant.RenewalRequest
		}
		if readErr != nil || grant.Disabled || !bytes.Equal(wire, stored) {
			http.Error(writer, "stale host request has no exact grant", http.StatusPreconditionFailed)
			return
		}
	}
	response, err := enrollment.enroll(request.Context(), snapshot.Epoch, peerIP, wire, enrollmentRequest, descriptor)
	if err != nil {
		if errors.Is(err, errStaleUnclaimedRenewal) {
			writer.Header().Set("X-TerraScale-Host-Enrollment-Error", staleUnclaimedRenewal)
			http.Error(writer, "stale unclaimed host renewal", http.StatusPreconditionFailed)
			return
		}
		http.Error(writer, "host enrollment held", http.StatusConflict)
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	_, _ = writer.Write(response)
}

func (enrollment *managedHostEnrollment) enroll(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if descriptor.IsStatic() {
		return enrollment.enrollStatic(ctx, epoch, peerIP, wire, request, descriptor)
	}

func (enrollment *managedHostEnrollment) enrollStatic(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if descriptor.Cell != enrollment.cell || descriptor.Region != string(enrollment.region) {
		return nil, errors.New("static host descriptor is outside this regional cell")
	}
	csr, err := hostenroll.ParseCSR(request.CSRPEM)
	if err != nil {
		return nil, err
	}
	instance, admission, err := enrollment.observeStatic(ctx, peerIP, request, descriptor)
	if err != nil {
		return nil, err
	}
	digest, err := descriptor.Digest()
	if err != nil {
		return nil, err
	}
	createKey := entityid.Derive("static-enrollment", enrollment.cell, descriptor.Node)
	var grant hostenroll.Grant
	var revision uint64
	if request.Operation == "renew" {
		prior, _, err := enrollment.grants.Read(ctx, request.InstanceID)
		if err != nil || prior.Disabled || prior.CreateKey != createKey || prior.DescriptorSHA256 != digest {
			return nil, errors.New("host renewal has no active exact enrollment grant")
		}
		var original hostenroll.Request
		if json.Unmarshal(prior.Request, &original, json.RejectUnknownMembers(true)) != nil ||
			original.IdentityPublicKey != request.IdentityPublicKey ||
			original.NATSUserPublicKey != request.NATSUserPublicKey || original.CSRPEM != request.CSRPEM {
			return nil, errors.New("host renewal changes an enrolled identity or CSR")
		}
		if time.Since(request.IssuedAt) > 5*time.Minute && !bytes.Equal(prior.RenewalRequest, wire) {
			return nil, errStaleUnclaimedRenewal
		}
		if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		grant, revision, err = enrollment.grants.ClaimRenew(ctx, request.InstanceID, wire, time.Now().UTC())
		if err != nil {
			return nil, err
		}
	} else {
		if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		grant, revision, err = enrollment.grants.Claim(ctx, hostenroll.Grant{SchemaVersion: 1,
			InstanceID: request.InstanceID, CreateKey: createKey, DescriptorSHA256: digest, Request: wire})
		if err != nil {
			return nil, err
		}
	}
	cached := grant.Response
	if request.Operation == "renew" {
		cached = grant.RenewalResponse
	}
	if len(cached) != 0 {
		if descriptor.IsController() {
			return enrollment.prepareRuntimeWorker(ctx, epoch, wire, cached)
		}
		return cached, enrollment.fencer.Guard(ctx, epoch)
	}
	jwt, chain, expires, err := enrollment.issuer.Issue(request, csr, descriptor.Node, time.Now().UTC())
	if err != nil {
		return nil, err
	}
	// The instance must still hold the peer address, under the admission it
	// registered with, when the credential is committed and released. A cell
	// spec adopted mid-request can change the admission: the registration
	// and response then settle on the one the last observation found.
	var responseWire []byte
	for attempt := 1; ; attempt++ {
		registration, err := enrollment.staticRegistration(ctx, request, descriptor, instance, admission)
		if err != nil {
			return nil, err
		}
		receipt, err := enrollment.controller.Register(ctx, registration)
		if err != nil {
			return nil, err
		}
		response := hostenroll.Response{SchemaVersion: 1, Operation: request.Operation,
			InstanceID: request.InstanceID, Node: descriptor.Node, DescriptorSHA256: digest,
			RequestSHA256: hostenroll.RequestSHA256(wire), Nonce: request.Nonce,
			RegistrationReceipt: receipt, Roles: admission.roles(),
			NATSUserJWT: jwt, TLSCertificatePEM: string(chain), ExpiresAt: expires}
		if enrollment.services != nil {
			response.NetBird = enrollment.services.netbird()
		}
		if err := response.Sign(enrollment.responseKey); err != nil {
			return nil, err
		}
		if responseWire, err = protocol.EncodeJSON(response); err != nil {
			return nil, err
		}
		if !descriptor.IsController() {
			responseWire, err = enrollment.prepareRuntimeWorker(ctx, epoch, wire, responseWire)
			if err != nil {
				return nil, err
			}
		}
		var again staticAdmission
		if instance, again, err = enrollment.observeStatic(ctx, peerIP, request, descriptor); err != nil {
			return nil, err
		}
		if reflect.DeepEqual(again, admission) {
			break
		}
		if attempt == 3 {
			return nil, errors.New("the cell spec keeps changing how this static host enrolls; retry")
		}
		admission = again
	}
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if descriptor.IsController() {
		current, currentRevision, err := hostenroll.ReadCurrentGrant(ctx, enrollment.js, request.InstanceID)
		if err != nil || currentRevision != revision || !reflect.DeepEqual(current, grant) ||
			!workerGrantAuthorizesPreparation(current, swarmruntime.WorkerRegistrationQuery{Request: wire, Response: responseWire}, time.Now().UTC()) {
			return nil, errors.New("controller enrollment no longer owns its exact live claim")
		}
		responseWire, err = enrollment.prepareRuntimeWorker(ctx, epoch, wire, responseWire)
		if err != nil {
			return nil, err
		}
	}
	if request.Operation == "renew" {
		err = enrollment.grants.FinishRenew(ctx, grant, revision, responseWire, time.Now().UTC())
	} else {
		_, err = enrollment.grants.Finish(ctx, grant, revision, responseWire)
	}
	if err != nil {
		return nil, err
	}
	// The commit is a KV CAS that fences no epoch: release the credential
	// only while this controller still holds authority. A held host retries
	// and the current leader replays the committed response.
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	return responseWire, nil
}

func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

func (store *GrantStore) Claim(ctx context.Context, candidate Grant) (Grant, uint64, error) {
	if store == nil || store.kv == nil || candidate.SchemaVersion != 1 || candidate.InstanceID == "" ||
		!entityid.Valid(candidate.CreateKey) || len(candidate.DescriptorSHA256) != 64 ||
		len(candidate.Request) == 0 || len(candidate.Request) > 16<<10 || len(candidate.Response) != 0 || candidate.Disabled ||
		candidate.OwnerToken != "" || !candidate.LeaseUntil.IsZero() || candidate.IdentityResetOperationID != "" || candidate.SwarmMembership != nil {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant candidate is invalid"))
	}
	claimToken := make([]byte, 32)
	if _, err := rand.Read(claimToken); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	candidate.OwnerToken = base64.RawURLEncoding.EncodeToString(claimToken)
	candidate.LeaseUntil = time.Now().UTC().Add(time.Minute)
	wire, err := json.Marshal(candidate)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	key := grantKey(candidate.InstanceID)
	if revision, err := store.kv.Create(ctx, key, wire); err == nil {
		return candidate, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return Grant{}, 0, fmt.Errorf("create host enrollment grant: %w", err)
	}
	entry, err := store.kv.Get(ctx, key)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(fmt.Errorf("read host enrollment grant: %w", err))
	}
	var current Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)) != nil ||
		current.SchemaVersion != 1 || current.InstanceID != candidate.InstanceID || current.CreateKey != candidate.CreateKey ||
		current.DescriptorSHA256 != candidate.DescriptorSHA256 || !bytes.Equal(current.Request, candidate.Request) || current.Disabled {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant differs from the immutable first request or is disabled"))
	}
	if len(current.Response) != 0 {
		return current, entry.Revision(), nil
	}
	if time.Now().Before(current.LeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	current.OwnerToken = candidate.OwnerToken
	current.LeaseUntil = candidate.LeaseUntil
	wire, err = json.Marshal(current)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	revision, err := store.kv.Update(ctx, key, wire, entry.Revision())
	if err != nil {
		wrapped := fmt.Errorf("recover host enrollment grant ownership: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return current, revision, nil
}

func (store *GrantStore) Finish(ctx context.Context, expected Grant, revision uint64, response []byte) (Grant, error) {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled || len(expected.Response) != 0 ||
		expected.OwnerToken == "" || !time.Now().Before(expected.LeaseUntil) ||
		len(response) == 0 || len(response) > 32<<10 {
		return Grant{}, mutationNotApplied(errors.New("host enrollment response cannot be committed"))
	}
	expected.Response = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return Grant{}, mutationNotApplied(err)
	}
	if _, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision); err != nil {
		wrapped := fmt.Errorf("commit host enrollment response: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, mutationNotApplied(wrapped)
		}
		return Grant{}, wrapped
	}
	return expected, nil
}

func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

func (store *GrantStore) ClaimRenew(ctx context.Context, instanceID string, request []byte,
	now time.Time,
) (Grant, uint64, error) {
	if len(request) == 0 || len(request) > 16<<10 {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal request is invalid"))
	}
	grant, revision, err := store.Read(ctx, instanceID)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	// Root reset provenance permits completing a grant without replaying an old response.
	resetPending := len(grant.Response) == 0 && entityid.Valid(grant.IdentityResetOperationID) &&
		grant.SchemaVersion == 1 && entityid.Valid(grant.CreateKey) && len(grant.DescriptorSHA256) == 64 &&
		len(grant.Request) != 0 && len(grant.Request) <= MaxRequestBytes && grant.OwnerToken == "" && grant.LeaseUntil.IsZero() && grant.TerminalOperationID == ""
	if grant.Disabled || len(grant.Response) == 0 && !resetPending {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant is disabled or incomplete"))
	}
	if bytes.Equal(grant.RenewalRequest, request) && len(grant.RenewalResponse) != 0 {
		return grant, revision, nil
	}
	if len(grant.RenewalRequest) != 0 && len(grant.RenewalResponse) == 0 && now.Before(grant.RenewalLeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	var previous Response
	if len(grant.RenewalResponse) != 0 {
		if json.Unmarshal(grant.RenewalResponse, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	} else if len(grant.RenewalRequest) == 0 && !resetPending {
		if json.Unmarshal(grant.Response, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	}
	token := make([]byte, 32)
	if _, err := rand.Read(token); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	grant.RenewalRequest = bytes.Clone(request)
	grant.RenewalResponse = nil
	grant.RenewalToken = base64.RawURLEncoding.EncodeToString(token)
	grant.RenewalLeaseUntil = now.Add(time.Minute)
	wire, err := json.Marshal(grant)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	next, err := store.kv.Update(ctx, grantKey(instanceID), wire, revision)
	if err != nil {
		wrapped := fmt.Errorf("claim host enrollment renewal: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return grant, next, nil
}

func (store *GrantStore) FinishRenew(ctx context.Context, expected Grant, revision uint64,
	response []byte, now time.Time,
) error {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled ||
		expected.RenewalToken == "" || !now.Before(expected.RenewalLeaseUntil) ||
		len(expected.RenewalRequest) == 0 || len(expected.RenewalResponse) != 0 ||
		len(response) == 0 || len(response) > 32<<10 {
		return mutationNotApplied(errors.New("host enrollment renewal cannot be committed"))
	}
	expected.RenewalResponse = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return mutationNotApplied(err)
	}
	_, err = store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return mutationNotApplied(err)
	}
	return err
}

