func verifyIdentityRekeyGlobalScope(cfg Config, reset authority.IdentityReset) error {
	home, err := globalControlHome(cfg.Controller.Global, cfg.NATS)
	if err != nil {
		return err
	}
	if (home == cfg.NATS.Cell) != (reset.GlobalLease != nil) {
		return errors.New("identity rekey must root-pin the global lease exactly in its topology home")
	}
	return nil
}

func globalControlHome(global *GlobalControlConfig, nats natscell.Config) (string, error) {
	home := natscell.LinkHome
	if nats.Embedded == nil || nats.Embedded.Link == nil {
		var err error
		if home, err = interRegionLink(nats).GlobalControlHome(nats.Cell); err != nil {
			return "", err
		}
	}
	if global != nil && global.Home != "" && global.Home != home {
		return "", errors.New("global control home must agree with the interregion topology")
	}
	return home, nil
}

func interRegionLink(nats natscell.Config) *natscell.InterRegion {
	if nats.Embedded == nil {
		return nil
	}
	return nats.Embedded.InterRegion
}

func (ir *InterRegion) GlobalControlHome(cell string) (string, error) {
	home := cell
	if ir != nil {
		home = ir.GlobalHome
		if ir.Topology != nil {
			if err := ir.matchTopology(cell, *ir.Topology); err != nil {
				return "", err
			}
			home = ir.Topology.Hub
		}
		if home != cell && !slices.Contains(ir.Peers, home) {
			return "", errors.New("interregion global home must be this region or a roster peer")
		}
	}
	if token, err := protocol.RegionToken(home); err != nil || token != home || token == protocol.GlobalScope {
		return "", errors.New("global control home must be a lowercase regional cell")
	}
	return home, nil
}

validatefiles.text:
func validateIdentityRekeyFiles(accepted bootstrapstart.AcceptedIdentity, files map[string][]byte) (Config, error) {
	if err := accepted.Validate(); err != nil {
		return Config{}, err
	}
	if len(files) != 4+len(identityRekeyLaunchFiles) || len(accepted.LaunchMaterialSHA256) != len(identityRekeyLaunchFiles) {
		return Config{}, errors.New("identity rekey requires exactly four config and four launch files")
	}
	for name, want := range accepted.ConfigSHA256 {
		if len(files[name]) == 0 || controllerSHA256(files[name]) != want {
			return Config{}, fmt.Errorf("identity rekey config %s differs from its accepted pin", name)
		}
	}
	for _, name := range identityRekeyLaunchFiles {
		if len(files[name]) == 0 || controllerSHA256(files[name]) != accepted.LaunchMaterialSHA256[name] {
			return Config{}, fmt.Errorf("identity rekey launch material %s differs from its accepted pin", name)
		}
	}
	sidecars := make([]bootstrap.ControllerConfigFile, 0, len(bootstrap.ControllerConfigFileNames))
	for _, name := range bootstrap.ControllerConfigFileNames {
		sidecars = append(sidecars, bootstrap.ControllerConfigFile{Name: name, Bytes: files[name], SHA256: accepted.ConfigSHA256[name]})
	}
	config, err := ValidateAcceptedControllerConfig(accepted, files[controllerConfigFilename], accepted.ConfigSHA256[controllerConfigFilename], sidecars)
	if err != nil {
		return Config{}, err
	}
	if config.Controller.SelfUpdateRoot != "" && config.Controller.SelfUpdateRoot != selfupdate.DefaultRoot {
		return Config{}, errors.New("identity rekey requires the fixed production release layout")
	}
	region, err := oci.ParseRegionConfig(files["oci-region.json"])
	if err != nil {
		return Config{}, err
	}
	if region.Region != oci.Region(accepted.Cell) {
		return Config{}, errors.New("identity rekey launch image belongs to another cell")
	}
	return config, nil
}

func ValidateAcceptedControllerConfig(accepted bootstrapstart.AcceptedIdentity, config []byte, want string,
	files []bootstrap.ControllerConfigFile,
) (Config, error) {
	if err := accepted.Validate(); err != nil {
		return Config{}, err
	}
	if len(files) != len(bootstrap.ControllerConfigFileNames) {
		return Config{}, errors.New("accepted controller sidecars are incomplete")
	}
	for i, file := range files {
		if file.Name != bootstrap.ControllerConfigFileNames[i] || file.SHA256 != accepted.ConfigSHA256[file.Name] {
			return Config{}, errors.New("controller sidecar differs from accepted identity")
		}
	}
	intent, err := oci.ParseRegionIntent(files[0].Bytes)
	if err != nil {
		return Config{}, err
	}
	return validateControllerConfig(controllerConfigBinding{
		DeploymentID: accepted.DeploymentID, Cell: oci.Region(accepted.Cell), Slot: accepted.Slot,
		SeedSlot: accepted.SeedSlot, Environment: accepted.Environment, ControllerSlots: accepted.ControllerSlots,
		ControllerConfig: config, ControllerConfigSHA256: want, ControllerFiles: files,
		Secrets: accepted.MaterialReferences, IntentGeneration: intent.Generation, IntentSHA256: files[0].SHA256,
	}, accepted.PrimaryPrivateIP)
}

func validateControllerConfig(manifest controllerConfigBinding, observedPrivateIP string) (Config, error) {
	if len(manifest.ControllerConfig) > bootstrap.MaxControllerConfigBytes ||
		controllerSHA256(manifest.ControllerConfig) != manifest.ControllerConfigSHA256 {
		return Config{}, errors.New("signed controller config differs from its signed digest")
	}
	cfg, err := decodeConfig(manifest.ControllerConfig)
	if err != nil {
		return Config{}, fmt.Errorf("decode signed controller config: %w", err)
	}
	hostConfig := cfg.Host
	if len(hostConfig.Roles) == 0 {
		hostConfig.Roles = nil
	}
	if cfg.NATS.Cell != strings.ToLower(string(manifest.Cell)) || cfg.NATS.Instance != manifest.Slot ||
		cfg.NATS.Replicas != len(manifest.ControllerSlots) || cfg.NATS.Embedded == nil ||
		cfg.Controller.CandidateID != entityid.Derive("controller", manifest.DeploymentID, string(manifest.Cell), manifest.Slot) ||
		!reflect.DeepEqual(hostConfig, HostConfig{}) ||
		cfg.Operator != (OperatorConfig{}) ||
		cfg.Controller.OciRegionConfig != controllerSidecarPath("oci-region.json") ||
		cfg.Controller.OciRegionIntentFile != controllerSidecarPath("oci-region-intent.json") ||
		cfg.Controller.PlacementConfig != controllerSidecarPath("placement.json") ||
		cfg.NATS.NKeySeedFile != "" || cfg.Controller.TrustKeyFile != "" || cfg.Controller.SpecTrust != nil {
		return Config{}, errors.New("signed controller config does not match role, slot, or fixed paths")
	}
	if observedPrivateIP != "" && (cfg.NATS.Embedded.Host != observedPrivateIP ||
		cfg.NATS.Embedded.RouteHost != observedPrivateIP) {
		return Config{}, errors.New("signed broker addresses differ from the observed primary VNIC")
	}
	address, addressErr := netip.ParseAddr(cfg.NATS.Embedded.Host)
	if addressErr != nil || !address.Is4() || !address.IsPrivate() || address.String() != cfg.NATS.Embedded.Host ||
		cfg.NATS.Embedded.RouteHost != cfg.NATS.Embedded.Host || cfg.NATS.Embedded.Port != 4222 ||
		cfg.NATS.Embedded.RoutePort != 6222 || cfg.NATS.URL != "tls://"+cfg.NATS.Embedded.Host+":4222" ||
		cfg.NATS.Embedded.StoreDir != "/var/lib/terrascale-orchestrator-controller/nats" ||
		cfg.NATS.Embedded.StoreMaxBytes < 2<<30 || cfg.NATS.Embedded.StoreMaxBytes > 8<<30 ||
		cfg.NATS.Embedded.RouteUser != "ts-route" || len(cfg.NATS.Embedded.Users) != 0 ||
		!slices.Equal(cfg.NATS.Embedded.BrokerIDs, manifest.ControllerSlots) ||
		len(cfg.NATS.Embedded.Routes) != len(manifest.ControllerSlots)-1 {
		return Config{}, errors.New("signed controller broker runtime is outside the reviewed shape")
	}
	seenRoutes := make(map[string]bool, len(cfg.NATS.Embedded.Routes))
	for _, route := range cfg.NATS.Embedded.Routes {
		if !strings.HasPrefix(route, "nats-route://") || !strings.HasSuffix(route, ":6222") ||
			seenRoutes[route] || route == "nats-route://"+cfg.NATS.Embedded.Host+":6222" {
			return Config{}, errors.New("signed controller route is invalid or duplicated")
		}
		peer, err := netip.ParseAddr(strings.TrimSuffix(strings.TrimPrefix(route, "nats-route://"), ":6222"))
		if err != nil || !peer.Is4() || !peer.IsPrivate() {
			return Config{}, errors.New("signed controller route address is invalid")
		}
		seenRoutes[route] = true
	}
	if cfg.Controller.HostEnrollmentListenAddress != cfg.NATS.Embedded.Host+":8443" {
		return Config{}, errors.New("host enrollment listener differs from the signed controller address")
	}
	if err := validateSignedObservability(cfg); err != nil {
		return Config{}, err
	}
	// The Machines API has no signed listener, TLS material or load balancer
	// yet (docs/machines-api.md, slice 7); until it does, a production
	// controller must not try to bind it.
	if cfg.Controller.MachinesAPI != nil {
		return Config{}, errors.New("signed controller config may not enable machines_api yet")
	}
	if _, err := buildSignerPolicy(cfg); err != nil {
		return Config{}, fmt.Errorf("signed controller operator grant: %w", err)
	}
	if len(manifest.ControllerFiles) != len(bootstrap.ControllerConfigFileNames) {
		return Config{}, errors.New("signed controller sidecars are incomplete")
	}
	for index, file := range manifest.ControllerFiles {
		if file.Name != bootstrap.ControllerConfigFileNames[index] ||
			controllerSHA256(file.Bytes) != file.SHA256 {
			return Config{}, errors.New("signed controller sidecar digest or name is invalid")
		}
	}
	secretFiles := make(map[string]struct{}, len(manifest.Secrets))
	for _, reference := range manifest.Secrets {
		if reference.Purpose == bootstrap.SecretRegionalShared ||
			reference.Purpose == bootstrap.SecretHostIssuer ||
			reference.Purpose == bootstrap.SecretController && reference.Slot == manifest.Slot ||
			(reference.Purpose == bootstrap.SecretSeedFounder || reference.Purpose == bootstrap.SecretSeedLedgerSigner) &&
				manifest.Slot == manifest.SeedSlot {
			secretFiles[reference.TargetFile] = struct{}{}
		}
	}
	paths := []string{cfg.NATS.CredentialsFile, cfg.NATS.TLS.CAFile, cfg.NATS.TLS.CertFile,
		cfg.NATS.TLS.KeyFile, cfg.NATS.Embedded.TLS.CAFile, cfg.NATS.Embedded.TLS.CertFile,
		cfg.NATS.Embedded.TLS.KeyFile, cfg.NATS.Embedded.RouteTLS.CAFile,
		cfg.NATS.Embedded.RouteTLS.CertFile, cfg.NATS.Embedded.RouteTLS.KeyFile,
		cfg.NATS.Embedded.RoutePasswordFile, cfg.NATS.Embedded.OperatorJWTFile,
		cfg.NATS.Embedded.SystemJWTFile, cfg.NATS.Embedded.CellJWTFile,
		cfg.NATS.Embedded.SystemCredentialsFile, cfg.NATS.Embedded.TicketPublicKeyFile,
		cfg.Controller.ResponseKeyFile, cfg.Controller.BrokerTicketKeyFile,
		cfg.Controller.HostNATSIssuerSeedFile, cfg.Controller.HostTLSIssuerKeyFile,
		cfg.Controller.HostTLSIssuerCertFile}
	for _, path := range paths {
		name := filepath.Base(path)
		if path == "" || path != filepath.Join(bootstrapstart.MaterialDirectory, name) {
			return Config{}, errors.New("controller credential path escapes the signed material directory")
		}
		if _, exists := secretFiles[name]; !exists {
			return Config{}, fmt.Errorf("controller credential %s is absent from signed material", name)
		}
	}
	// Interregion and link files come from an adopted material generation, whose
	// pins restart admission checks (TS-668); they too live in the directory.
	for _, path := range append(cfg.NATS.Embedded.InterRegion.Files(), cfg.NATS.Embedded.Link.Files()...) {
		if path != filepath.Join(bootstrapstart.MaterialDirectory, filepath.Base(path)) {
			return Config{}, errors.New("interregion or link credential path escapes the signed material directory")
		}
	}
	// The C# TerraBase member CA is host-issuer material: configured exactly
	// when signed, at its fixed paths, as the live credential check requires.
	_, signedCACert := secretFiles["terrabase-member-ca.pem"]
	_, signedCAKey := secretFiles["terrabase-member-ca.key"]
	if cfg.Controller.TerraBaseCACertFile != "" || cfg.Controller.TerraBaseCAKeyFile != "" || signedCACert || signedCAKey {
		if !signedCACert || !signedCAKey ||
			cfg.Controller.TerraBaseCACertFile != filepath.Join(bootstrapstart.MaterialDirectory, "terrabase-member-ca.pem") ||
			cfg.Controller.TerraBaseCAKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "terrabase-member-ca.key") {
			return Config{}, errors.New("TerraBase member CA is not the signed slot material")
		}
	}
	// Without the member CA no member gets a certificate or starts.
	if _, terraBase := cfg.Controller.Workloads[terrabase.Role]; terraBase && !signedCACert {
		return Config{}, errors.New("a signed TerraBase workload profile needs the signed member CA")
	}
	if err := validateWorkloadProfiles(cfg.NATS.Cell, cfg.Controller.Workloads); err != nil {
		return Config{}, fmt.Errorf("signed controller workloads: %w", err)
	}
	if err := validateAutoscaleConfig(cfg.Controller.Autoscale, cfg.Controller.Workloads); err != nil {
		return Config{}, fmt.Errorf("signed controller autoscale: %w", err)
	}
	if path := cfg.NATS.Embedded.MembershipCredentialsFile; path != "" {
		if _, signed := secretFiles["membership.creds"]; !signed ||
			path != filepath.Join(bootstrapstart.MaterialDirectory, "membership.creds") {
			return Config{}, errors.New("membership credentials are not the signed slot material")
		}
	}
	if cfg.Controller.ResponseKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, manifest.Slot+"-response.key") ||
		cfg.Controller.BrokerTicketKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "ticket.key") ||
		cfg.Controller.HostNATSIssuerSeedFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-nats-issuer.seed") ||
		cfg.Controller.HostTLSIssuerKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-tls-issuer-key.pem") ||
		cfg.Controller.HostTLSIssuerCertFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-tls-issuer-cert.pem") {
		return Config{}, errors.New("controller response or broker-ticket key does not match the slot")
	}
	intent, err := oci.ParseRegionIntent(manifest.ControllerFiles[0].Bytes)
	if err != nil || intent.Generation != manifest.IntentGeneration ||
		manifest.ControllerFiles[0].SHA256 != manifest.IntentSHA256 {
		return Config{}, errors.New("controller regional intent differs from signed anchor pin")
	}
	region, err := oci.ParseRegionConfig(manifest.ControllerFiles[1].Bytes)
	if err != nil || region.Validate(intent) != nil || region.Region != manifest.Cell {
		return Config{}, errors.New("controller fleet config differs from signed region")
	}
	var placement managedPlacementSettings
	if err := protocol.DecodeStrict(manifest.ControllerFiles[2].Bytes, &placement, bootstrap.MaxControllerSidecarBytes); err != nil ||
		placement.Environment != manifest.Environment || placement.MemberRole == "" {
		return Config{}, errors.New("controller placement config differs from signed environment")
	}
	// Controller start refuses the same overlap; refuse it before signing.
	if _, exists := cfg.Controller.Workloads[placement.MemberRole]; exists {
		return Config{}, fmt.Errorf("placement member role %q overlaps a generic delivery workload profile", placement.MemberRole)
	}
	return cfg, nil
}

// ConfigVersion is the only supported role-config contract.
// Legacy configs require newly produced and signed desired state before rollout.
const ConfigVersion = roleconfig.Version

func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

// Package roleconfig names the signed role-configuration wire contract.
package roleconfig

// Version rejects legacy configs rather than activating formerly disabled services.
// Version 2 requires freshly produced and signed switch-free desired state;
// readers never rewrite or re-sign historical configuration bytes.
const Version = 2

cleanup.text:
func unlinkRetiredIdentityInput(dir int, name string, uid, gid uint32, check func() error) error {
	if !slices.Contains([]string{"identity.json", "anchor.json", controllerManifestFilename, "initial-formation.json"}, name) {
		return errors.New("identity rekey cleanup refuses an unrelated name")
	}
	if check == nil {
		return errors.New("identity rekey cleanup requires verified shared completion")
	}
	if err := check(); err != nil {
		return err
	}
	var stat unix.Stat_t
	if err := unix.Fstatat(dir, name, &stat, unix.AT_SYMLINK_NOFOLLOW); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	if stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Uid != uid || stat.Gid != gid || stat.Nlink != 1 || stat.Mode&0o022 != 0 {
		return errors.New("identity rekey cleanup refuses indirect or unowned authority input")
	}
	if err := unix.Unlinkat(dir, name, 0); err != nil {
		return err
	}
	return unix.Fsync(dir)
}

journalnode.text:
func identityRekeyJournalNode(wire []byte, service identityRekeyActiveService) (string, error) {
	return identityRekeyJournalNodeBefore(wire, service, time.Now().Round(0).UTC())
}

func identityRekeyJournalNodeBefore(wire []byte, service identityRekeyActiveService, startedBefore time.Time) (string, error) {
	if len(wire) == 0 || len(wire) > 32<<10 {
		return "", errors.New("live Raft node journal observation is absent or oversized")
	}
	pid := strconv.FormatUint(uint64(service.PID), 10)
	node := ""
	for line := range bytes.SplitSeq(bytes.TrimSpace(wire), []byte("\n")) {
		var row map[string]string
		if err := json.Unmarshal(line, &row); err != nil {
			return "", err
		}
		if row["_PID"] != pid || row["_SYSTEMD_INVOCATION_ID"] != service.Invocation || row["_SYSTEMD_UNIT"] != selfupdate.ControllerUnit {
			return "", errors.New("Raft node record is not from the observed controller invocation")
		}
		micros, err := strconv.ParseInt(row["__REALTIME_TIMESTAMP"], 10, 64)
		if err != nil || micros <= 0 || startedBefore.IsZero() || !time.UnixMicro(micros).Before(startedBefore) {
			return "", errors.New("controller invocation does not predate this identity reset")
		}
		fields := strings.Fields(row["MESSAGE"])
		if len(fields) != 4 || fields[0] != "["+pid+"]" || fields[1] != "[INF]" || fields[2] != "Node:" || len(fields[3]) != 8 {
			return "", errors.New("Raft node record is not an exact NATS startup observation")
		}
		for _, char := range fields[3] {
			if !(char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' || char >= '0' && char <= '9') {
				return "", errors.New("invalid advertised Raft node identity")
			}
		}
		if node != "" && node != fields[3] {
			return "", errors.New("controller invocation advertised conflicting Raft node identities")
		}
		node = fields[3]
	}
	return node, nil
}

stopped.text:
func verifyIdentityRekeyControllerStopped(ctx context.Context, serviceUID uint32) error {
	probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	command := exec.CommandContext(probeCtx, "/usr/bin/systemctl", "show", selfupdate.ControllerUnit,
		"--property=LoadState,ActiveState,SubState,MainPID,ControlPID,KillMode")
	command.WaitDelay = time.Second
	output, err := command.Output()
	if err != nil {
		return fmt.Errorf("inspect stopped controller service: %w", err)
	}
	if err := validateIdentityRekeyStoppedState(output); err != nil {
		return err
	}
	return verifyIdentityRekeyNoServiceProcesses("/proc", serviceUID)
}

func validateIdentityRekeyStoppedState(wire []byte) error {
	fields := map[string]string{}
	for line := range strings.SplitSeq(strings.TrimSpace(string(wire)), "\n") {
		key, value, ok := strings.Cut(line, "=")
		if !ok || fields[key] != "" {
			return errors.New("invalid controller service observation")
		}
		fields[key] = value
	}
	if fields["LoadState"] != "loaded" || fields["ActiveState"] != "inactive" || fields["SubState"] != "dead" ||
		fields["MainPID"] != "0" || fields["ControlPID"] != "0" || fields["KillMode"] != "control-group" {
		return errors.New("identity rekey requires an inactive/dead controller with no main or control process")
	}
	return nil
}

func verifyIdentityRekeyNoServiceProcesses(directory string, serviceUID uint32) error {
	if serviceUID == 0 {
		return errors.New("identity rekey requires a dedicated non-root controller service UID")
	}
	entries, err := os.ReadDir(directory)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		if _, err := strconv.ParseUint(entry.Name(), 10, 32); err != nil {
			continue
		}
		wire, err := os.ReadFile(filepath.Join(directory, entry.Name(), "status"))
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		found := false
		for line := range strings.SplitSeq(string(wire), "\n") {
			if !strings.HasPrefix(line, "Uid:") {
				continue
			}
			values := strings.Fields(strings.TrimPrefix(line, "Uid:"))
			if len(values) != 4 {
				return errors.New("invalid local process UID observation")
			}
			for _, value := range values {
				uid, err := strconv.ParseUint(value, 10, 32)
				if err != nil {
					return err
				}
				if uint32(uid) == serviceUID {
					return errors.New("identity rekey refused a remaining controller service process")
				}
			}
			found = true
		}
		if !found {
			return errors.New("local process UID observation is missing")
		}
	}
	return nil
}

replace.text:
func replaceIdentityRekeyFile(dir int, name string, wire []byte, uid, gid uint32) error {
	if len(wire) == 0 || len(wire) > bootstrap.MaxControllerConfigBytes || filepath.Base(name) != name || name == "." || name == ".." {
		return errors.New("invalid identity rekey file")
	}
	var existing unix.Stat_t
	if err := unix.Fstatat(dir, name, &existing, unix.AT_SYMLINK_NOFOLLOW); err == nil {
		if existing.Mode&unix.S_IFMT != unix.S_IFREG || existing.Nlink != 1 || existing.Uid != uid || existing.Mode&0o002 != 0 {
			return errors.New("identity rekey destination is not an owned regular file")
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	temporary := ".identity-rekey." + rand.Text()
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0o444)
	if err != nil {
		return err
	}
	defer unix.Unlinkat(dir, temporary, 0)
	file := os.NewFile(uintptr(fd), temporary)
	defer file.Close()
	if err := file.Chown(int(uid), int(gid)); err != nil {
		return err
	}
	if err := file.Chmod(0o444); err != nil {
		return err
	}
	if n, err := file.Write(wire); err != nil || n != len(wire) {
		return errors.Join(err, io.ErrShortWrite)
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := unix.Renameat(dir, temporary, dir, name); err != nil {
		return err
	}
	return unix.Fsync(dir)
}

