telemetry.text:
type switchingFencer struct {
	mu       sync.Mutex
	snapshot authority.Snapshot
}

func (fencer *switchingFencer) Current() authority.Snapshot {
	fencer.mu.Lock()
	defer fencer.mu.Unlock()
	return fencer.snapshot
}

func (*switchingFencer) Guard(context.Context, uint64) error { return nil }

func (fencer *switchingFencer) set(snapshot authority.Snapshot) {
	fencer.mu.Lock()
	fencer.snapshot = snapshot
	fencer.mu.Unlock()
}

func startWorkloadAutoscale(cell string, config *AutoscaleConfig, profiles map[string]WorkloadProfile,
	specs []workload.ServiceSpec, hosts *host.Controller,
	fencer authority.Fencer,
	nativeReleases *nativeHistory,
) (*workload.Reconciler, *hostTelemetry, error) {
	resources := profileResources(profiles)
	requests := loadRequests(resources)
	load := &hostTelemetry{fencer: fencer, requests: requests,
		load: hostload.NewAggregator(hostload.AggregatorConfig{Requests: requests})}
	var releaseResources func(context.Context, []host.Desired, map[string]placement.Resources) (map[string]placement.Resources, error)
	var writer workload.DesiredWriter = hosts
	if nativeReleases != nil {
		releaseResources = func(ctx context.Context, desired []host.Desired, profiles map[string]placement.Resources) (map[string]placement.Resources, error) {
			resolved, err := nativeReleases.resources(ctx, desired, profiles)
			if err == nil {
				load.setResources(resolved)
			}
			return resolved, err
		}
		writer = nativeReleases
	}
	reconciler, err := workload.New(workload.Config{Cell: cell, Specs: specs, Profiles: resources, ReleaseResources: releaseResources,
		Hosts: hosts, Writer: writer, Fencer: fencer, Signals: load.load,
		Logf: log.Printf})
	if err != nil {
		return nil, nil, fmt.Errorf("start workload reconciler: %w", err)
	}
	hosts.SetLoadSink(load.record)
	return reconciler, load, nil
}

func loadRequests(resources map[string]placement.Resources) map[string]hostload.Request {
	requests := make(map[string]hostload.Request, len(resources))
	for role, request := range resources {
		requests[role] = hostload.Request{CPUCores: float64(request.CPU), MemoryBytes: request.MemoryBytes}
	}
	return requests
}

func (t *hostTelemetry) current() bool {
	snapshot := t.fencer.Current()
	if !snapshot.CanMutate() {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = 0
		return false
	}
	if t.epoch != snapshot.Epoch {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = snapshot.Epoch
	}
	return true
}

func (t *hostTelemetry) record(origin hostload.Origin, report hostload.Report) error {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return authority.ErrFenced
	}
	return t.load.Record(origin, report)
}

// nodes is every node's latest fresh report while this controller leads.
func (t *hostTelemetry) nodes() []hostload.NodeLoad {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return nil
	}
	return t.load.Nodes()
}

func (t *hostTelemetry) samples() []observability.Sample {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return nil
	}
	return hostLoadSamples(t.load)
}

// Utilization windows cannot mix samples normalized against different requests.
func (t *hostTelemetry) setResources(resources map[string]placement.Resources) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.setRequests(loadRequests(resources))
}

// setRequests is called with mu held, including throughout usage recording.
func (t *hostTelemetry) setRequests(requests map[string]hostload.Request) {
	if maps.Equal(t.requests, requests) {
		return
	}
	t.requests = requests
	t.load.Reset()
	t.load.SetRequests(requests)
}

func withAutoscaleSamples(collect func(context.Context) []observability.Sample, reconciler workloadObservation,
	load *hostTelemetry,
) func(context.Context) []observability.Sample {
	if reconciler == nil && load == nil {
		return collect
	}
	return func(ctx context.Context) []observability.Sample {
		samples := collect(ctx)
		if reconciler != nil && reconciler.Leading() {
			samples = append(samples, autoscaleSamples(reconciler)...)
		}
		if load != nil {
			samples = append(samples, load.samples()...)
		}
		return samples
	}
}

func hostLoadSamples(load *hostload.Aggregator) []observability.Sample {
	if load == nil {
		return nil
	}
	var samples []observability.Sample
	for _, node := range load.Nodes() {
		member := strings.ToLower(node.Origin.Node)
		labels := observability.L("member", member)
		samples = append(samples, observability.Sample{Metric: observability.HistHostReceivedAt,
			Labels: labels, Value: float64(node.At.UnixMilli())})
		incomplete := 0.0
		if node.Report.Host.FilesystemsIncomplete {
			incomplete = 1
		}
		samples = append(samples, observability.Sample{Metric: observability.HistHostFSIncomplete, Labels: labels, Value: incomplete})
		for _, value := range []struct {
			metric string
			value  *float64
		}{{observability.HistHostCPUUtilization, node.Report.Host.CPU},
			{observability.HistHostMemoryRatio, node.Report.Host.Memory},
			{observability.HistHostDiskRatio, node.Report.Host.Disk}} {
			if value.value != nil {
				samples = append(samples, observability.Sample{Metric: value.metric, Labels: labels, Value: *value.value})
			}
		}
		if node.Report.Host.CPUCores > 0 {
			samples = append(samples, observability.Sample{Metric: observability.HistHostCPUCores,
				Labels: labels, Value: float64(node.Report.Host.CPUCores)})
		}
		if node.Report.Host.MemoryBytes > 0 {
			samples = append(samples, observability.Sample{Metric: observability.HistHostMemoryTotal,
				Labels: labels, Value: float64(node.Report.Host.MemoryBytes)})
		}
		for _, filesystem := range node.Report.Host.Filesystems {
			labels := observability.L("member", member, "role", filesystem.Role,
				"path", filesystem.Path, "device", strconv.FormatUint(filesystem.Device, 10))
			used := float64(filesystem.SizeBytes - filesystem.AvailBytes)
			samples = append(samples,
				observability.Sample{Metric: observability.HistHostFSUsed, Labels: labels, Value: used},
				observability.Sample{Metric: observability.HistHostFSSize, Labels: labels, Value: float64(filesystem.SizeBytes)},
				observability.Sample{Metric: observability.HistHostFSRatio, Labels: labels, Value: used / float64(filesystem.SizeBytes)},
				observability.Sample{Metric: observability.HistHostFSFiles, Labels: labels, Value: float64(filesystem.Files)},
				observability.Sample{Metric: observability.HistHostFSFilesFree, Labels: labels, Value: float64(filesystem.FilesFree)})
		}
		for _, role := range node.Report.Roles {
			service := observability.L("member", member, "service", role.Role)
			if role.CPUCores != nil {
				samples = append(samples, observability.Sample{Metric: observability.HistServiceCPUCores,
					Labels: service, Value: *role.CPUCores})
			}
			if role.MemoryBytes != nil {
				samples = append(samples, observability.Sample{Metric: observability.HistServiceMemoryUsed,
					Labels: service, Value: float64(*role.MemoryBytes)})
			}
			if wan := role.WAN; wan != nil && wan.Fresh(time.Now()) && wan.Validate() == nil {
				for _, source := range wan.Sources {
					labels := observability.L("member", member, "node", node.Origin.Node, "role", role.Role,
						"receiver_region", wan.ReceiverRegion, "source_region", source.SourceRegion)
					samples = append(samples, observability.Sample{Metric: observability.HistTerraBaseWANObservedAt,
						Labels: labels, Value: float64(wan.ObservedAt.UnixMilli())})
					for _, reading := range []struct {
						metric string
						value  *float64
					}{{observability.HistTerraBaseWANLagGroups, source.LagGroups},
						{observability.HistTerraBaseWANStaleness, source.StalenessSeconds},
						{observability.HistTerraBaseWANMembers, source.Members},
						{observability.HistTerraBaseWANUnregistered, source.Unregistered},
						{observability.HistTerraBaseWANConflicts, source.Conflicts},
						{observability.HistTerraBaseWANAheadFailures, source.AheadFailuresTotal}} {
						if reading.value != nil {
							samples = append(samples, observability.Sample{Metric: reading.metric, Labels: labels, Value: *reading.value})
						}
					}
				}
			}
			block := role.TerraBase
			if block == nil {
				continue
			}
			labels := observability.L("member", member, "role", role.Role)
			samples = append(samples,
				observability.Sample{Metric: observability.HistTerraBaseConnections, Labels: labels, Value: float64(block.Connections)},
				observability.Sample{Metric: observability.HistTerraBaseStorage, Labels: labels, Value: float64(block.StorageBytes)},
				observability.Sample{Metric: observability.HistTerraBaseLagSeq, Labels: labels, Value: float64(block.ReplicationLagSeq)},
				observability.Sample{Metric: observability.HistTerraBaseWriteQPS, Labels: labels, Value: block.WriteQPS})
		}
	}
	return samples
}

func (c *Controller) SetLoadSink(sink LoadSink) {
	if sink == nil {
		c.loadSink.Store(nil)
		return
	}
	c.loadSink.Store(&sink)
}

func New(config Config) (*Reconciler, error) {
	if config.Hosts == nil || config.Writer == nil || config.Fencer == nil || !nameRE.MatchString(config.Cell) {
		return nil, errors.New("workload reconciler requires cell, host view, writer and fencer")
	}
	specs, profiles, err := prepareServices(config.Specs, config.Profiles)
	if err != nil {
		return nil, err
	}
	config.Profiles = profiles
	if config.Interval <= 0 {
		config.Interval = DefaultInterval
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	if config.Logf == nil {
		config.Logf = func(string, ...any) {}
	}
	return &Reconciler{config: config, specs: specs, history: make(map[string]autoscale.History),
		goal: make(map[string]int), last: make(map[string]Result)}, nil
}

func (r *Reconciler) Signals() autoscale.Source {
	if r == nil {
		return nil
	}
	return r.config.Signals
}

func (a *Aggregator) Reset() {
	a.mu.Lock()
	clear(a.nodes)
	clear(a.runs)
	a.mu.Unlock()
}

func NewAggregator(config AggregatorConfig) *Aggregator {
	if config.MinInterval <= 0 {
		config.MinInterval = DefaultMinInterval
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = DefaultStaleAfter
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	config.Requests = maps.Clone(config.Requests)
	return &Aggregator{config: config, nodes: make(map[string]*nodeState), runs: make(map[seriesKey]run)}
}

// SetRequests replaces the per-role resource requests, for example after a
// cell spec amendment. Samples already recorded keep the request they were
// computed with.
func (a *Aggregator) SetRequests(requests map[string]Request) {
	a.mu.Lock()
	a.config.Requests = maps.Clone(requests)
	a.mu.Unlock()
}

func (a *Aggregator) Record(origin Origin, report Report) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, a.config.Requests)
}

// RecordRequests normalizes one authenticated host against its actual summed
// task reservations. Other hosts keep their own requests and sample windows.
func (a *Aggregator) RecordRequests(origin Origin, report Report, requests map[string]Request) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, requests)
}

// record is called with the aggregator lock held.
func (a *Aggregator) record(origin Origin, report Report, requests map[string]Request) error {
	if err := report.Validate(); err != nil {
		return err
	}
	now := a.config.Now()
	node, known := a.nodes[origin.Node]
	if known && now.Sub(node.latest.At) < a.config.MinInterval {
		return ErrTooFrequent
	}
	if !known {
		if len(a.nodes) >= maxNodes {
			// Full: forget every node that is no longer reporting, even if
			// a long window could still use its older samples.
			a.pruneLocked(now, a.config.StaleAfter)
		}
		if len(a.nodes) >= maxNodes {
			return ErrTooManyNodes
		}
		node = &nodeState{store: autoscale.NewWindowStore(nodeRetention, a.nodePoints()),
			series: make(map[seriesKey]time.Time)}
		a.nodes[origin.Node] = node
	}
	node.latest = NodeLoad{Origin: origin, At: now, Report: report}
	// Recording under the aggregator lock keeps one node's samples in
	// receive order and its store from being pruned mid-record.
	for _, role := range report.Roles {
		target := autoscale.Target{Cell: origin.Cell, Environment: origin.Environment, Role: role.Role}
		for name, value := range roleSignals(role, report.Host, requests[role.Role]) {
			node.store.Record(target, name, autoscale.Sample{At: now, Value: value})
			key := seriesKey{target: target, signal: name}
			node.series[key] = now
			current := a.runs[key]
			switch gap := now.Sub(current.last); {
			case current.last.IsZero() || gap > a.config.StaleAfter:
				current.since, current.holes = now, nil
			case gap > 2*a.config.MinInterval:
				// Samples arrive in receive order, so holes stay sorted and
				// the expired ones are at the front.
				expired := 0
				for expired < len(current.holes) && now.Sub(current.holes[expired].end) > nodeRetention {
					expired++
				}
				current.holes = append(current.holes[expired:], hole{end: now, length: gap})
			}
			current.last = now
			a.runs[key] = current
		}
	}
	return nil
}

func (a *Aggregator) Nodes() []NodeLoad {
	now := a.config.Now()
	a.mu.Lock()
	a.pruneLocked(now, nodeRetention)
	out := make([]NodeLoad, 0, len(a.nodes))
	for _, node := range a.nodes {
		if now.Sub(node.latest.At) <= a.config.StaleAfter {
			out = append(out, node.latest)
		}
	}
	a.mu.Unlock()
	slices.SortFunc(out, func(x, y NodeLoad) int { return strings.Compare(x.Origin.Node, y.Origin.Node) })
	return out
}

func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}
